package com.aditya.fefo.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="audit_logs") public class AuditLog { @Id private UUID id; @Column(name="actor_id") private UUID actorId; private String action; @Column(name="entity_type") private String entityType; @Column(name="entity_id") private UUID entityId; private Long quantity; @Column(name="product_id") private UUID productId; @Column(name="batch_id") private UUID batchId; @Column(name="reservation_id") private UUID reservationId; private String reason; @Column(name="created_at") private Instant createdAt; protected AuditLog(){} public AuditLog(UUID actorId,String action,String entityType,UUID entityId,Long quantity,UUID productId,UUID batchId,UUID reservationId,String reason){this.id=UUID.randomUUID();this.actorId=actorId;this.action=action;this.entityType=entityType;this.entityId=entityId;this.quantity=quantity;this.productId=productId;this.batchId=batchId;this.reservationId=reservationId;this.reason=reason;this.createdAt=Instant.now();} public UUID getId(){return id;} public UUID getActorId(){return actorId;} public String getAction(){return action;} public String getEntityType(){return entityType;} public UUID getEntityId(){return entityId;} public Long getQuantity(){return quantity;} public UUID getProductId(){return productId;} public UUID getBatchId(){return batchId;} public UUID getReservationId(){return reservationId;} public String getReason(){return reason;} public Instant getCreatedAt(){return createdAt;} }
